-- Baseline of the schema as generated by Hibernate from the entities before Flyway took over.
-- Unqualified on purpose: Flyway's default schema (spring.flyway.schemas) applies.

create table tb_brands (active boolean not null, created_date timestamp(6), id bigint generated by default as identity, last_modified_date timestamp(6), version bigint default 0 not null, name varchar(100) not null unique, created_by varchar(255), last_modified_by varchar(255), primary key (id));
create table tb_product_suppliers (active boolean not null, created_date timestamp(6), id bigint generated by default as identity, last_modified_date timestamp(6), product_id bigint not null, supplier_id bigint not null, supplier_product_code varchar(64), created_by varchar(255), last_modified_by varchar(255), primary key (id), unique (product_id, supplier_id));
create table tb_products (active boolean not null, allow_negative_stock boolean not null, minimum_stock numeric(19,3) not null, price numeric(19,2) not null, reorder_point numeric(19,3) not null, stock_quantity numeric(19,3) not null, brand_id bigint, created_date timestamp(6), id bigint generated by default as identity, last_modified_date timestamp(6), version bigint not null, barcode varchar(14) unique, unit_of_measure varchar(20) not null check ((unit_of_measure in ('UNIT','KILOGRAM','GRAM','LITER','MILLILITER','METER','CENTIMETER','BOX','PIECE'))), sku varchar(64) not null unique, category varchar(100) not null, subcategory varchar(100), name varchar(150) not null, description varchar(1000), created_by varchar(255), last_modified_by varchar(255), primary key (id));
create table tb_refresh_tokens (created_at timestamp(6) with time zone not null, expires_at timestamp(6) with time zone not null, grace_used_at timestamp(6) with time zone, id bigint generated by default as identity, revoked_at timestamp(6) with time zone, user_id bigint not null, revoked_reason varchar(10) check ((revoked_reason in ('ROTATED','LOGOUT','REVOKED'))), token_hash varchar(64) not null unique, primary key (id));
create table tb_suppliers (active boolean not null, created_date timestamp(6), id bigint generated by default as identity, last_modified_date timestamp(6), version bigint default 0 not null, tax_id varchar(14) unique, phone varchar(20), email varchar(150), legal_name varchar(150) not null, trade_name varchar(150), created_by varchar(255), last_modified_by varchar(255), primary key (id));
create table tb_users (active boolean not null, failed_attempts integer default 0 not null, created_date timestamp(6), id bigint generated by default as identity, last_login_at timestamp(6) with time zone, last_modified_date timestamp(6), locked_until timestamp(6) with time zone, version bigint default 0 not null, role varchar(20) not null check ((role in ('ADMIN','MANAGER','CASHIER','STOCK'))), name varchar(100) not null, password_hash varchar(100) not null, email varchar(150) not null unique, created_by varchar(255), last_modified_by varchar(255), primary key (id));
create index idx_refresh_tokens_user_id on tb_refresh_tokens (user_id);
alter table if exists tb_product_suppliers add constraint FKfkwr4urhd85wpwcqfyoo9ivsa foreign key (product_id) references tb_products;
alter table if exists tb_product_suppliers add constraint FKnjry84l7wteakr91esmpcd81h foreign key (supplier_id) references tb_suppliers;
alter table if exists tb_products add constraint FKj0574x2g0g413jqi20vjy74hm foreign key (brand_id) references tb_brands;
alter table if exists tb_refresh_tokens add constraint FKidkw733t1mfbs1psj59n76oj4 foreign key (user_id) references tb_users;
